return ['domain'=>'reportedip-hive','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de','project-id-version'=>'ReportedIP Hive Light 1.3.8','pot-creation-date'=>'2026-10-11T08:20:06+00:00','po-revision-date'=>'2026-10-11T08:20:06+00:00','messages'=>['ReportedIP Hive Light'=>'ReportedIP Hive Light','https://reportedip.com/products/wordpress-plugin/'=>'https://reportedip.com/products/wordpress-plugin/','Lightweight brute-force login protection with optional community-powered IP reputation checks.'=>'Schlanker Schutz vor Brute-Force-Angriffen auf die Anmeldung, optional mit IP-Reputationsabfragen aus der Community.','Patrick Schlesinger'=>'Patrick Schlesinger','https://reportedip.com'=>'https://reportedip.com','Dashboard'=>'Dashboard','Settings'=>'Einstellungen','Blocked IPs'=>'Gesperrte IPs','Whitelist'=>'Whitelist','Added %s to the whitelist.'=>'%s wurde zur Whitelist hinzugefügt.','Could not add the entry — please provide a valid IPv4/v6 address or CIDR range.'=>'Der Eintrag konnte nicht hinzugefügt werden. Bitte gib eine gültige IPv4/v6-Adresse oder einen CIDR-Bereich an.','Testing connection…'=>'Verbindung wird getestet …','Please enter an access key first.'=>'Bitte gib zuerst einen Access Key ein.','Could not reach reportedip.com. Check your network and try again.'=>'reportedip.com ist nicht erreichbar. Prüfe deine Netzwerkverbindung und versuche es erneut.','Active blocks'=>'Aktive Sperren','Blocks (last 24 h)'=>'Sperren (letzte 24 Std.)','Attempts (last 24 h)'=>'Versuche (letzte 24 Std.)','Whitelisted IPs'=>'IPs auf der Whitelist','Last 24 h'=>'Letzte 24 Std.','Last 7 days'=>'Letzte 7 Tage','Last 30 days'=>'Letzte 30 Tage','All time'=>'Gesamter Zeitraum','Defended attacks'=>'Abgewehrte Angriffe','Each block represents one IP that was prevented from logging in after exceeding the configured thresholds.'=>'Jede Sperre steht für eine IP, die nach Überschreiten der eingestellten Schwellenwerte an der Anmeldung gehindert wurde.','Operation mode'=>'Betriebsmodus','Community Network'=>'Community Network','IP reputation lookups + queued reports active.'=>'IP-Reputationsabfragen und Meldungs-Warteschlange aktiv.','Local Shield'=>'Local Shield','No external requests. Switch to Community Network in Settings to enable reputation lookups.'=>'Keine externen Anfragen. Wechsle in den Einstellungen zu Community Network, um Reputationsabfragen zu aktivieren.','API health & quota'=>'API-Status und Kontingent','Outbound calls this hour: %1$d / %2$d'=>'Ausgehende Anfragen in dieser Stunde: %1$d / %2$d','Rolling 1-hour window. When exhausted, reputation lookups are skipped (login still proceeds, fail-open).'=>'Gleitendes Zeitfenster von 1 Stunde. Ist das Kontingent erschöpft, werden Reputationsabfragen übersprungen (die Anmeldung läuft trotzdem weiter, fail-open).','Report queue'=>'Meldungs-Warteschlange','pending'=>'ausstehend','processing'=>'in Bearbeitung','completed'=>'abgeschlossen','failed'=>'fehlgeschlagen','Reports are queued in the database and dispatched by a 15-minute cron job — never from the login path. Failed rows retry up to 3 times.'=>'Meldungen landen in einer Warteschlange in der Datenbank und werden alle 15 Minuten per Cron-Job versendet, niemals direkt bei der Anmeldung. Fehlgeschlagene Einträge werden bis zu 3-mal wiederholt.','Recent activity'=>'Letzte Aktivitäten','No login attempts recorded yet.'=>'Bisher wurden keine Anmeldeversuche erfasst.','Connection'=>'Verbindung','Protection'=>'Schutz','Privacy'=>'Datenschutz','Brute-force protection for WordPress logins'=>'Schutz vor Brute-Force-Angriffen für WordPress-Anmeldungen','Save Changes'=>'Änderungen speichern','Blocked IP addresses'=>'Gesperrte IP-Adressen','IP whitelist'=>'IP-Whitelist','Add to whitelist'=>'Zur Whitelist hinzufügen','IP address or CIDR range'=>'IP-Adresse oder CIDR-Bereich','IPv4, IPv6 or IPv4 CIDR (e.g. 203.0.113.0/24).'=>'IPv4, IPv6 oder IPv4-CIDR (z. B. 203.0.113.0/24).','Reason (optional)'=>'Grund (optional)','e.g. Office VPN'=>'z. B. Büro-VPN','Expires (optional)'=>'Läuft ab (optional)','Leave blank for a permanent entry.'=>'Leer lassen für einen dauerhaften Eintrag.','Current whitelist'=>'Aktuelle Whitelist','No whitelist entries yet.'=>'Noch keine Einträge in der Whitelist.','Insufficient permissions.'=>'Unzureichende Berechtigungen.','Invalid IP address.'=>'Ungültige IP-Adresse.','None — use REMOTE_ADDR (default)'=>'Keiner, REMOTE_ADDR verwenden (Standard)','Operation Mode'=>'Betriebsmodus','Local Shield (recommended)'=>'Local Shield (empfohlen)','Uses only your site\'s data. No external requests.'=>'Nutzt nur die Daten deiner Website. Keine externen Anfragen.','Community Network (optional)'=>'Community Network (optional)','Enabling Community Network mode will:'=>'Wenn du den Modus Community Network aktivierst, wird das Plugin:','Send blocked IP addresses to reportedip.com when your site detects an attack.'=>'Gesperrte IP-Adressen an reportedip.com senden, sobald deine Website einen Angriff erkennt.','Query reportedip.com during login attempts to check IP reputation.'=>'Bei Anmeldeversuchen reportedip.com abfragen, um die Reputation der IP zu prüfen.','Send only the IP address, a category ID and a short comment with each report. Usernames never leave your server, neither in plain text nor hashed.'=>'Mit jeder Meldung nur die IP-Adresse, eine Kategorie-ID und einen kurzen Kommentar senden. Benutzernamen verlassen deinen Server nie, weder im Klartext noch gehasht.','Identify your site only via your Community Access Key — no domain or contact information is transmitted.'=>'Deine Website nur über deinen Community Access Key identifizieren. Domain oder Kontaktdaten werden nicht übertragen.','Legal basis: GDPR Art. 6(1)(f), legitimate interest in network security.'=>'Rechtsgrundlage: Art. 6 Abs. 1 lit. f DSGVO, berechtigtes Interesse an der Netzwerksicherheit.','Community Access Key'=>'Community Access Key','Access Key'=>'Access Key','Need an access key? Visit reportedip.com.'=>'Du brauchst einen Access Key? Besuche reportedip.com.','API Endpoint'=>'API-Endpunkt','Default endpoint. Override via the reportedip_hive_api_endpoint filter.'=>'Standard-Endpunkt. Überschreiben kannst du ihn über den Filter reportedip_hive_api_endpoint.','Test connection'=>'Verbindung testen','Reverse Proxy'=>'Reverse Proxy','Trusted Proxy Header'=>'Vertrauenswürdiger Proxy-Header','Only set this if your site sits behind a reverse proxy (Cloudflare, AWS, NGINX) that overrides the header for every incoming request. Otherwise the header can be spoofed.'=>'Setze das nur, wenn deine Website hinter einem Reverse Proxy (Cloudflare, AWS, NGINX) liegt, der den Header bei jeder eingehenden Anfrage überschreibt. Andernfalls lässt sich der Header fälschen.','Brute-force thresholds'=>'Schwellenwerte für Brute-Force-Angriffe','Failed-login threshold'=>'Schwellenwert für fehlgeschlagene Anmeldungen','Block an IP after this many failed login attempts.'=>'Eine IP nach so vielen fehlgeschlagenen Anmeldeversuchen sperren.','Time window (minutes)'=>'Zeitfenster (Minuten)','Time window during which failed attempts are counted.'=>'Zeitfenster, in dem fehlgeschlagene Versuche gezählt werden.','Password-spray detection'=>'Erkennung von Password-Spraying','Distinct usernames threshold'=>'Schwellenwert für verschiedene Benutzernamen','Block an IP that fails logins against this many distinct usernames.'=>'Eine IP sperren, deren Anmeldung bei so vielen verschiedenen Benutzernamen fehlschlägt.','Blocking behaviour'=>'Sperrverhalten','Automatic blocking'=>'Automatisches Sperren','If disabled, attempts are logged but no block is enforced (report-only mode).'=>'Wenn deaktiviert, werden Versuche protokolliert, aber nicht gesperrt (Nur-Melden-Modus).','Progressive block duration'=>'Ansteigende Sperrdauer','Increases block duration with each repeat offense (5 min → 15 min → 30 min → 24 h → 48 h → 7 days).'=>'Verlängert die Sperrdauer bei jedem erneuten Verstoß (5 Min. → 15 Min. → 30 Min. → 24 Std. → 48 Std. → 7 Tage).','Report-only mode'=>'Nur-Melden-Modus','Detect and report attacks but never block. Useful for staging environments.'=>'Angriffe erkennen und melden, aber nie sperren. Praktisch für Staging-Umgebungen.','Show advanced (block ladder)'=>'Erweitert anzeigen (Sperrstufen)','Block ladder (CSV minutes)'=>'Sperrstufen (Minuten, kommagetrennt)','Cache & retention'=>'Cache und Aufbewahrung','Reputation cache duration (hours)'=>'Cache-Dauer für Reputation (Stunden)','Negative cache duration (hours)'=>'Cache-Dauer für negative Ergebnisse (Stunden)','API queue retention (days)'=>'Aufbewahrung der API-Warteschlange (Tage)','Uninstall'=>'Deinstallieren','Delete all data on uninstall'=>'Beim Deinstallieren alle Daten löschen','Drop all plugin tables and options when the plugin is deleted. Recommended OFF for forensic reasons.'=>'Entfernt alle Tabellen und Optionen des Plugins, wenn es gelöscht wird. Aus forensischen Gründen wird empfohlen, dies AUS zu lassen.','Privacy notice'=>'Datenschutzhinweis','This plugin processes IP addresses to detect attacks. Username inputs are stored hashed (SHA-256, salted with wp_salt()), never in plaintext. In Local Shield mode, no data leaves your server. In Community Network mode, blocked IP addresses are shared with reportedip.com together with an event category and a short comment; usernames are never transmitted. See the readme.txt "External services" and "Privacy" sections for full details.'=>'Dieses Plugin verarbeitet IP-Adressen, um Angriffe zu erkennen. Eingegebene Benutzernamen werden gehasht gespeichert (SHA-256, gesalzen mit wp_salt()), nie im Klartext. Im Modus Local Shield verlassen keine Daten deinen Server. Im Modus Community Network werden gesperrte IP-Adressen zusammen mit einer Ereigniskategorie und einem kurzen Kommentar an reportedip.com übermittelt, Benutzernamen werden nie übertragen. Alle Details findest du in der readme.txt in den Abschnitten „External services“ und „Privacy“.','No blocked IPs yet'=>'Noch keine gesperrten IPs','When the plugin blocks an attacker, you will see them listed here. Configure thresholds in Settings → Protection.'=>'Sobald das Plugin einen Angreifer sperrt, erscheint er hier. Die Schwellenwerte legst du unter Einstellungen → Schutz fest.','Configure Protection'=>'Schutz konfigurieren','Hive Light is complete and stays free. Need a Web Application Firewall, two-factor authentication or multisite support? The free Full Edition and the optional Hive PRO subscription build on the same engine.'=>'Hive Light ist vollständig und bleibt kostenlos. Du brauchst eine Web Application Firewall, Zwei-Faktor-Authentifizierung oder Multisite-Unterstützung? Die kostenlose Full Edition und das optionale Abo Hive PRO bauen auf derselben Engine auf.','ReportedIP Hive Full Edition & PRO'=>'ReportedIP Hive Full Edition & PRO','Security Focused'=>'Security Focused','GDPR Compliant'=>'GDPR Compliant','Made in Germany'=>'Made in Germany','Settings saved.'=>'Einstellungen gespeichert.','IP Address'=>'IP-Adresse','Type'=>'Typ','Count'=>'Anzahl','Last attempt'=>'Letzter Versuch','%s ago'=>'vor %s','Reason'=>'Grund','Attempts'=>'Versuche','Blocked until'=>'Gesperrt bis','Status'=>'Status','Unblock selected'=>'Ausgewählte entsperren','Never expires'=>'Läuft nie ab','Expired'=>'Abgelaufen','in %s'=>'in %s','Inactive'=>'Inaktiv','Active'=>'Aktiv','ReportedIP Hive Light Setup'=>'ReportedIP Hive Light einrichten','Setup'=>'Einrichtung','Welcome'=>'Willkommen','Done'=>'Fertig','Skip setup'=>'Einrichtung überspringen','Setup progress'=>'Fortschritt der Einrichtung','Welcome to ReportedIP Hive Light'=>'Willkommen bei ReportedIP Hive Light','This short setup configures the brute-force counter and lets you choose whether the plugin should also consult the reportedip.com community database during login attempts.'=>'Diese kurze Einrichtung konfiguriert den Zähler für Brute-Force-Angriffe. Außerdem legst du fest, ob das Plugin bei Anmeldeversuchen zusätzlich die Community-Datenbank von reportedip.com abfragen soll.','You can change everything later under Settings → ReportedIP Hive Light.'=>'Du kannst alles später unter Einstellungen → ReportedIP Hive Light ändern.','Get started'=>'Los geht’s','Checks IP reputation against the reportedip.com community database during login attempts and shares blocked IPs back. Usernames are never sent.'=>'Prüft bei Anmeldeversuchen die IP-Reputation in der Community-Datenbank von reportedip.com und teilt gesperrte IPs zurück. Benutzernamen werden nie gesendet.','Community Access Key (optional)'=>'Community Access Key (optional)','Required only for Community Network. A free key is available at reportedip.com.'=>'Nur für Community Network erforderlich. Einen kostenlosen Key bekommst du auf reportedip.com.','Continue'=>'Weiter','Protection settings'=>'Schutzeinstellungen','Enable automatic blocking'=>'Automatisches Sperren aktivieren','When disabled, attempts are logged but no block is enforced.'=>'Wenn deaktiviert, werden Versuche protokolliert, aber nicht gesperrt.','You are protected.'=>'Du bist geschützt.','ReportedIP Hive Light is active and listening to login attempts. Visit Settings → ReportedIP Hive Light any time to fine-tune thresholds, manage the whitelist, or review blocked IPs.'=>'ReportedIP Hive Light ist aktiv und überwacht Anmeldeversuche. Unter Einstellungen → ReportedIP Hive Light kannst du jederzeit Schwellenwerte feinjustieren, die Whitelist verwalten oder gesperrte IPs prüfen.','Try a wrong-password login a few times to see the protection trigger.'=>'Melde dich ein paarmal mit falschem Passwort an, um zu sehen, wie der Schutz greift.','Whitelist your office IP under Whitelist before any security drills.'=>'Setze deine Büro-IP unter Whitelist auf die Whitelist, bevor du Sicherheitstests durchführst.','Review the Privacy notice in Settings → Privacy if you intend to enable Community Network mode.'=>'Lies den Datenschutzhinweis unter Einstellungen → Datenschutz, wenn du den Modus Community Network aktivieren möchtest.','Open dashboard'=>'Dashboard öffnen','IP / CIDR'=>'IP / CIDR','Expires'=>'Läuft ab','Added by'=>'Hinzugefügt von','Added'=>'Hinzugefügt','Remove selected'=>'Ausgewählte entfernen','(none)'=>'(keine)','Never'=>'Nie','(system)'=>'(System)','No access key provided.'=>'Kein Access Key angegeben.','Could not reach reportedip.com: %s'=>'reportedip.com ist nicht erreichbar: %s','Connection successful. Your access key is valid.'=>'Verbindung erfolgreich. Dein Access Key ist gültig.','Connection failed: invalid access key. Check the key and try again.'=>'Verbindung fehlgeschlagen: ungültiger Access Key. Prüfe den Key und versuche es erneut.','Connection failed (HTTP %d). Please retry in a few minutes.'=>'Verbindung fehlgeschlagen (HTTP %d). Bitte versuche es in ein paar Minuten erneut.','Every 15 minutes'=>'Alle 15 Minuten','Access denied. Your IP address has been temporarily blocked due to suspicious activity.'=>'Zugriff verweigert. Deine IP-Adresse wurde wegen verdächtiger Aktivitäten vorübergehend gesperrt.','Access denied. This IP address has been flagged by the community.'=>'Zugriff verweigert. Diese IP-Adresse wurde von der Community als verdächtig markiert.','Full Edition & PRO'=>'Full Edition & PRO','Access denied'=>'Zugriff verweigert','This plugin processes IP addresses to detect brute-force login attacks against your site. IP addresses are stored in the site database and may be displayed in the WordPress admin under "ReportedIP Hive Light → Blocked IPs".'=>'Dieses Plugin verarbeitet IP-Adressen, um Brute-Force-Angriffe auf die Anmeldung deiner Website zu erkennen. IP-Adressen werden in der Datenbank der Website gespeichert und können im WordPress-Adminbereich unter „ReportedIP Hive Light → Gesperrte IPs“ angezeigt werden.','Usernames submitted to the login form are stored as a SHA-256 hash, salted with the site\'s wp_salt(). Usernames are never transmitted, neither in plain text nor hashed.'=>'Im Anmeldeformular eingegebene Benutzernamen werden als SHA-256-Hash gespeichert, gesalzen mit dem wp_salt() der Website. Benutzernamen werden nie übertragen, weder im Klartext noch gehasht.','In Local Shield mode (default), no data leaves your server. In Community Network mode, blocked IP addresses are shared with reportedip.com for collective threat intelligence, together with an event category and a short comment such as the number of failed logins. The site is identified only by the Community Access Key — no domain or contact information is transmitted.'=>'Im Modus Local Shield (Standard) verlassen keine Daten deinen Server. Im Modus Community Network werden gesperrte IP-Adressen für die gemeinsame Bedrohungsanalyse an reportedip.com übermittelt, zusammen mit einer Ereigniskategorie und einem kurzen Kommentar, etwa der Anzahl fehlgeschlagener Anmeldungen. Die Website wird nur über den Community Access Key identifiziert. Domain oder Kontaktdaten werden nicht übertragen.','ReportedIP Hive Light is active. <a href="%s">Configure protection</a> at Settings &rarr; ReportedIP Hive Light.'=>'ReportedIP Hive Light ist aktiv. <a href="%s">Konfiguriere den Schutz</a> unter Einstellungen &rarr; ReportedIP Hive Light.','Dismiss notice'=>'Hinweis ausblenden']];